<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Holder\PlatformIdentityTrustedClientAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the PlatformIdentityTrustedClientAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class PlatformIdentityTrustedClientAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getTrustedClient returns null on a freshly created holder.
     */
    public function testTrustedClientNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithPlatformIdentityTrustedClientAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isTrustedClientAssigned());
        $this->assertNull($holder->getTrustedClient());
    }
}
class ImplWithPlatformIdentityTrustedClientAttributeHolderUnitTest
{
    use PlatformIdentityTrustedClientAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedTrustedClientRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultTrustedClient();
    }
}
